%[text] %[text:anchor:T_8A930495] # Third-Order One-Dimensional Hermitian Basis Functions
%[text] Computation of the third-order one-dimensional Hermitian basis functions, their first and second-order derivatives which are needed for the discretization of the Euler-Bernoulli beam formulation, namely,
%[text] $\\begin{array}{l}\nN\_1(\\xi) = \\frac{1}{4} \\left( \\xi - 1 \\right)^2 \\left( \\xi + 2 \\right) \\\\\nN\_2(\\xi) = \\frac{1}{8} \\left( \\xi - 1 \\right)^2 \\left( \\xi + 1 \\right) \\\\\nN\_3(\\xi) =  - \\frac{1}{4} \\left( \\xi + 1 \\right)^2 \\left( \\xi - 2 \\right) \\\\\nN\_4(\\xi) = \\frac{1}{8} \\left( \\xi - 1 \\right) \\left( \\xi + 1 \\right)^2\n\\end{array}$
%[text] for $\\xi \\in \\left\[ -1, 1\\right\]$
%[text] ![HermitianBasisFunctions.png](text:image:1bbe)
%[text:tableOfContents]{"heading":"**Table of Contents**"}
function dN = computeThirdOrderHermitianBasisFunctions1D(xi)
%[text] %[text:anchor:H_BF619794] It computes the third-order one-dimensional Hermitian basis functions.
%[text] %[text:anchor:H_9945A214] ## Function description
%[text] %[text:anchor:H_8E89FA9A]  **Input** :
%[text]  `xi` : Parametric coordinate in closed domain \[-1, 1\] 
%[text] %[text:anchor:H_FC0663F5]  **Output** :
%[text]  `dN` : Array containing the third order Hermitian shape functions dN(:, 1), their first-order derivatives $\\frac{\\partial N\_i (\\xi) }{\\partial \\xi}$ stored in array `dN(:, 2)` and their second-order derivatives $\\frac{\\partial^2 N\_i (\\xi) }{\\partial \\xi^2}$ stored in array `dN(:, 3)`
%[text] %[text:anchor:H_7DD35F7E] ## Function Implementation
%[text] %[text:anchor:H_DCF9EBED] ### Input validation
arguments
    xi (1, 1) double {mustBeInRange(xi, -1, 1)}
end
%[text] %[text:anchor:H_E8F3B80B] ### Read input and initialize output
    tol = eps;
    if xi < -1 - tol || xi > 1 + tol
        error("The provided parametric location xi = %f is outside the bounds [-1, 1]", xi);
    end
    dN = zeros(4, 3);
%[text] %[text:anchor:H_C56933D1] ### Hermitian shape functions
%[text] %[text:anchor:H_0F8A3773] $N\_i(\\xi)$ where $\\xi \\in \\left\[ -1, 1\\right\]$ and $i = 1,\\ldots,4$
        dN(:, 1) = [ ((xi - 1)^2*(xi + 2))/4
                     ((xi - 1)^2*(xi + 1))/8
                    -((xi + 1)^2*(xi - 2))/4
                     ((xi - 1)*(xi + 1)^2)/8];
%[text] %[text:anchor:H_7915DC5F] ### First-order derivatives of the Hermitian shape functions
%[text] $\\frac{\\partial N\_i (\\xi) }{\\partial \\xi}$
        dN(:, 2) = [       (3*xi^2)/4 - 3/4
                    (3*xi^2)/8 - xi/4 - 1/8
                           3/4 - (3*xi^2)/4
                    (3*xi^2)/8 + xi/4 - 1/8];
%[text] %[text:anchor:H_3000E01C] ### Second-order derivatives of the Hermitian shape functions
%[text] $\\frac{\\partial^2 N\_i (\\xi) }{\\partial \\xi^2}$
        dN(:, 3) = [      (3*xi)/2
                    (3*xi)/4 - 1/4
                         -(3*xi)/2
                    (3*xi)/4 + 1/4];
%[text] 
end

